pub fn fromName(name: []const u8) anyerror {
    var low: usize = 0;
    var high: usize = names.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        switch (std.mem.order(u8, name, std.mem.span(names[middle]))) {
            .eq => return values[middle],
            .lt => high = middle,
            .gt => low = middle + 1,
        }
    }
    return error.RuntimeBoundaryFailure;
}
test "engine errors retain every generated identity" {
    for (names, values) |name, value| {
        try std.testing.expectEqual(value, fromName(std.mem.span(name)));
    }
    try std.testing.expectEqual(error.RuntimeBoundaryFailure, fromName(""));
    try std.testing.expectEqual(error.RuntimeBoundaryFailure, fromName("_antfly_unknown_error_name_"));
}
test "engine errors preserve model-aware chunk failure identities" {
    for ([_]anyerror{ error.StaleChunkContinuation, error.IncompleteChunkCoverage, error.InvalidChunkCoordinates, error.ChunkOutputTooLarge, error.SourceVersionChanged, error.EmbeddingIdentityMismatch, error.InvalidChunkReplay }) |err| {
        try std.testing.expectEqual(err, fromName(@errorName(err)));
    }
}
